import { z } from 'zod';
import { promptReferenceSchema } from '../agent/diagramEdit';

export const chatSettingsSchema = z.object({
  model: z.string().max(200).default(''),
  effort: z.string().max(40).default(''),
  sandbox: z.enum(['read-only', 'workspace-write', 'danger-full-access']).default('danger-full-access')
});
export type ChatSettings = z.infer<typeof chatSettingsSchema>;
export const chatResumeSchema = z.object({ sessionId: z.string().trim().uuid().transform(value => value.toLowerCase()) });
export const chatCanvasTargetSchema = z.object({ workspaceInstanceId: z.string().min(1).max(200), documentId: z.string().min(1).max(200) }).strict();
export type ChatCanvasTarget = z.infer<typeof chatCanvasTargetSchema>;
/** Browser-captured context, pinned to the same revision as the visible selection. */
export const chatReferenceSchema = z.object({
  canvas: chatCanvasTargetSchema, canvasName: z.string().max(200), displayNodeId: z.string().min(1).max(200),
  reference: promptReferenceSchema, ascii: z.string().max(100_000)
}).strict();
export type ChatReference = z.infer<typeof chatReferenceSchema>;
export const chatReferencesSchema = z.array(chatReferenceSchema).max(20, 'Select at most 20 references.')
  .refine(refs => refs.reduce((size, ref) => size + ref.ascii.length, 0) <= 100_000, 'Selected references are too large. Select a smaller region.');
export const chatSendSchema = chatSettingsSchema.extend({ text: z.string().trim().min(1).max(100_000), requestId: z.string().uuid(), references: chatReferencesSchema.optional(), canvas: chatCanvasTargetSchema.optional() });
export type ChatSend = z.infer<typeof chatSendSchema>;
export const chatReadCanvasSchema = chatSettingsSchema.extend({ requestId: z.string().uuid(), canvas: chatCanvasTargetSchema });
export type ChatReadCanvas = z.infer<typeof chatReadCanvasSchema>;
export const chatAnswerSchema = z.object({
  decision: z.enum(['accept', 'decline']).optional(),
  answers: z.record(z.string(), z.array(z.string().max(20_000))).optional()
});
export type ChatAnswer = z.infer<typeof chatAnswerSchema>;
export interface CommandAction { type: string; name?: string; path?: string; query?: string; command?: string }
export interface ChatFileChange { path: string; kind: string; diff: string; added: number; removed: number; omittedChars?: number }
export interface ChatItem {
  id: string; kind: 'user' | 'assistant' | 'reasoning' | 'tool' | 'plan' | 'interaction' | 'notice';
  title?: string; text: string; status: string; turnId?: string; sourceType?: string;
  references?: ChatReference[];
  phase?: 'commentary' | 'partial_answer' | 'final_answer';
  command?: { command: string; actions: CommandAction[]; source?: string; processId?: string; exitCode?: number; durationMs?: number };
  changes?: ChatFileChange[];
  plan?: { step: string; status: string }[];
  omittedChars?: number;
  /** Transport preview only. Canonical retained details remain on the server. */
  detailAvailable?: boolean;
}
export interface ChatQuestion { id: string; header: string; question: string; isSecret?: boolean; options?: { label: string; description: string }[] | null }
export interface ChatApproval { id: string; kind: 'approval' | 'input' | 'permissions'; title: string; detail: string; questions?: ChatQuestion[]; turnId?: string }
export interface ChatGeneration {
  metadata: import('../../core/diagrams/canvasGeneration').CanvasGeneration;
  source: ChatCanvasTarget; stableWorkspaceId?: string; viewId: string; parentViewId: string;
  history?: import('../../core/diagrams/canvasHistory').CanvasHistoryRecord;
  usageBaseline?: import('../../core/diagrams/canvasGeneration').CanvasGeneration['usage'];
}
export interface ChatGenerationRequest { error?: string; requestId: string; signature: string; runId: string; candidates: { viewId: string; chatId: string; name: string }[] }
export interface ChatSession {
  generation?: ChatGeneration;
  generationRequests?: ChatGenerationRequest[];
  toolDefinitions?: { type: 'function'; name: string; description: string; inputSchema: Record<string, unknown> }[];
  tokenUsage?: import('../../core/diagrams/canvasGeneration').CanvasGeneration['usage'];

  /** Imported native threads retain their prompt and tools; Reload tools explicitly adds Agent Chat's MCP tools. */
  origin?: 'codex';
  /** Marks imports that have adopted Agent Chat's default rather than native access. */
  accessDefaultApplied?: true;
  canvasTools?: boolean;
  toolsReloadedAt?: string;
  canvasContext?: { canvas?: ChatCanvasTarget; references: ChatReference[] };
  id: string; threadId: string; title: string; cwd: string; createdAt: string; updatedAt: string;
  settings: ChatSettings; status: 'idle' | 'running' | 'interrupted' | 'failed'; turnId?: string | null;
  items: ChatItem[]; pending: ChatApproval[]; error?: string | null; usage?: number;
  requestIds: string[];
  schemaVersion?: 2;
  activity?: string | null;
  turnStartedAt?: string;
  completedAt?: string | null;
}
export type ChatSessionSummary = Pick<ChatSession, 'id' | 'title' | 'cwd' | 'updatedAt' | 'status'> & { parentChatId?: string; settings?: ChatSettings };
export interface ChatModel { id: string; name: string; efforts: string[]; defaultEffort: string; isDefault: boolean }
export interface ChatInfo { cwd: string; models: ChatModel[]; account: string }
export type ChatUpdate =
  | { type: 'item'; item: ChatItem }
  | { type: 'delta'; id: string; kind: ChatItem['kind']; text: string; turnId?: string; sourceType?: string }
  | { type: 'state'; patch: Partial<Pick<ChatSession, 'status' | 'turnId' | 'pending' | 'error' | 'usage' | 'updatedAt' | 'settings' | 'title' | 'activity' | 'turnStartedAt' | 'completedAt' | 'toolsReloadedAt' | 'canvasTools' | 'tokenUsage' | 'generation'>> };
export type ChatEvent = ChatUpdate | { type: 'snapshot'; session: ChatSession; partial?: boolean }
  | { type: 'snapshot-part'; items: ChatItem[]; final: boolean } | { type: 'batch'; events: ChatUpdate[] };

export const MAX_TOOL_TEXT = 128_000;
export function boundedToolText(text: string, omittedChars = 0) {
  const omitted = Math.max(0, text.length - MAX_TOOL_TEXT);
  return { text: omitted ? text.slice(-MAX_TOOL_TEXT) : text, omittedChars: omittedChars + omitted };
}

// Indexes and change metadata are transient; persisted history remains plain JSON.
const indexes = new WeakMap<ChatItem[], Map<string, number>>();
const changes = new WeakMap<ChatItem[], { previous: WeakRef<ChatItem[]>; start: number }>();
function indexFor(items: ChatItem[]) {
  let index = indexes.get(items);
  if (!index) { index = new Map(items.map((item, i) => [item.id, i])); indexes.set(items, index); }
  return index;
}
export function findChatItem(session: ChatSession, id: string) { return session.items[indexFor(session.items).get(id) ?? -1]; }

/** Find the affected suffix without scanning completed history on each streamed update. */
export function chatChangeStart(previous: ChatItem[], next: ChatItem[]): number {
  if (previous === next) return next.length;
  let cursor = next, start = next.length;
  for (let depth = 0; depth < 512; depth++) {
    const change = changes.get(cursor), parent = change?.previous.deref();
    if (!change || !parent) return 0;
    start = Math.min(start, change.start);
    if (parent === previous) return start;
    cursor = parent;
  }
  return 0;
}

/** Shared replay semantics keep a reconnect snapshot and live deltas equivalent. */
export function reduceChatEvent(session: ChatSession, event: ChatEvent): ChatSession {
  if (event.type === 'snapshot') return event.session;
  if (event.type === 'snapshot-part') return { ...session, items: [...session.items, ...event.items] };
  let items = session.items, index = indexFor(items), copiedIndex = false, start = items.length;
  let result = session;
  for (const update of event.type === 'batch' ? event.events : [event]) {
    if (update.type === 'state') { result = { ...result, ...update.patch }; continue; }
    const id = update.type === 'item' ? update.item.id : update.id;
    const position = index.get(id) ?? items.length;
    const old = items[position];
    let item: ChatItem = update.type === 'item' ? update.item : {
      ...(old ?? { id, kind: update.kind, status: 'inProgress', turnId: update.turnId, sourceType: update.sourceType }),
      text: (old?.text ?? '') + update.text
    };
    if (item.kind === 'tool') item = { ...item, ...boundedToolText(item.text, item.omittedChars) };
    if (items === session.items) items = items.slice();
    if (!old) {
      if (!copiedIndex) { index = new Map(index); copiedIndex = true; }
      index.set(id, position);
    }
    items[position] = item;
    start = Math.min(start, position);
  }
  if (items !== session.items) {
    indexes.set(items, index);
    changes.set(items, { previous: new WeakRef(session.items), start });
  }
  return { ...result, items };
}

sources.domain/mapping/agent/canvasReply.ts:
export const canvasReplyLimit = 64 * 1024 * 1024;
export const mutationCommands = new Set(['project-diagrams', 'canvas-view', 'apply', 'apply-diagram-revision', 'apply-diagram-context', 'create-diagrams', 'create-document', 'copy-document', 'saved']);
/** Count the entire encoded envelope, including command ID and escaped/multibyte text. */
export function canvasReply(command: { id: string; method: string }, result: { value?: unknown; error?: string }, limit = canvasReplyLimit) {
  const body = JSON.stringify({ commandId: command.id, ...result });
  const bytes = new TextEncoder().encode(body).byteLength;
  const error = `CANVAS_REPLY_TOO_LARGE: method=${command.method} actualBytes=${bytes} limitBytes=${limit}${mutationCommands.has(command.method) ? '; mutation outcome may be unknown; retry the identical requestId' : '; use a smaller read'} `;
  return { body: bytes > limit ? JSON.stringify({ commandId: command.id, error }) : body, bytes, oversized: bytes > limit };
}

sources.domain/mapping/agent/capabilities.ts:
import { canvasMethods } from './contracts';
import { z } from 'zod';

const readActions = ['canvas.read', 'nodes.get', 'nodes.list', 'nodes.variants', 'nodes.alternatives', 'edges.list'] as const;
const editActions = ['nodes.promoteAlternative', 'nodes.selectAlternative', 'nodes.removeAlternative', 'nodes.sidePanel', 'nodes.reviewVariant', 'nodes.selectRevision', 'nodes.setPresentation', 'nodes.highlight', 'nodes.removeHighlights', 'nodes.draw', 'nodes.replace', 'nodes.move', 'nodes.patchDiagram', 'nodes.collapse', 'edges.create', 'edges.update', 'edges.remove'] as const;
export const CANVAS_EXEC_DESCRIPTION = `Execute synchronous JavaScript with canvas, nodes and edges; use return, not await. Use the connected MCP tool directly, without creating a shell MCP client or rediscovering these common methods.
Consecutive mutations batch by default: one browser command, one version increment and one undo entry per batch. A read, nodes.setSourceMappings or nodes.setJumps flushes preceding edits. Successful script completion flushes the final batch. An uncaught script error discards pending edits. A rejected batch applies none of its operations; earlier flushed batches remain committed.
Mutations require expectedVersion from a current read and a unique requestId. Retry an uncertain transport outcome with exactly the same arguments and requestId. In-script mutation calls return queued handles {id, nodeId} or {id, edgeId}, not full nodes. Use a read if subsequent code needs committed data. The tool response is {value, transaction:{version, receipts:[{method,nodeId?,edgeId?,status,highlightId?,color?,markdownUrl?}]}}. Receipts describe each batch at commit time; later edits can supersede them. Use contentNodeIds to save one highlight spanning multiple nodes in the same diagram, with one color, saved ID and link. Highlight receipts contain the actual saved ID and ready-to-use markdownUrl. Use those links verbatim. Return only the fields you need from reads.
Set mode: "immediate" only for legacy scripts requiring full per-edit results and separate commits. It returns the original full-node transaction format.
Example read: const r = canvas.read({level:"small"}); return {version:r.version, targets:r.nodes.map(n => ({nodeId:n.id, anchors:Object.values(n.content?.structure.nodes ?? {}).map(a => ({id:a.id,label:a.label}))}))};
Example batch (with current IDs and expectedVersion): for (const target of targets) nodes.highlight({...target,color:"blue"});
Read results contain version and nodes; diagram ASCII is content.ascii and anchors are content.structure.nodes. Use returned IDs verbatim. Additional methods remain available through canvas-api-search.`;

export function canvasCapabilities(mode: 'read' | 'edit') {
  return [...readActions, ...(mode === 'edit' ? editActions : [])].map(name => ({ name,
    description: canvasMethods[name].description, inputSchema: z.toJSONSchema(canvasMethods[name].schema) }));
}
export function canvasAgentInstructions(mode: 'read' | 'edit') {
  return `${CANVAS_EXEC_DESCRIPTION}\nCanvas capabilities (${mode}):\n${JSON.stringify(canvasCapabilities(mode))}`;
}

