import { z } from 'zod';
import { agentContextSnapshotSchema, type AgentContextSnapshot } from '../../core/agents/agentContext';
import { contentNodeAnchorSchema, type ContentNodeAnchor } from '../../core/diagrams/diagramConnection';
import type { DiagramInput } from '../../core/diagrams/diagram';
import type { DiagramRevision } from '../../core/diagrams/diagramRevisionEditor';
import { promptTemplateSelectionSchema, type PromptOperation } from './promptTemplates';

const id = z.string().min(1).max(200);
const label = z.string().trim().min(1).max(200);
const line = z.number().int().positive();
/** References are pinned to an immutable revision when inserted; later canvas changes never alter them. */
export const promptReferenceSchema = z.discriminatedUnion('kind', [
  z.object({ kind: z.literal('diagram'), label, diagramId: id, revisionId: id }).strict(),
  z.object({ kind: z.literal('nodes'), label, diagramId: id, revisionId: id, nodeIds: z.array(id).max(500),
    range: z.object({ startLine: line, endLine: line, startColumn: line, endColumn: line }).strict()
      .refine(range => range.startLine <= range.endLine && range.startColumn <= range.endColumn, 'Invalid node range') }).strict()
]);
export type PromptReference = z.infer<typeof promptReferenceSchema>;
const promptFields = {
  /** Panel-owned conversation identity and its last completed context. */
  llmSessionId: id.optional(),
  agentContext: agentContextSnapshotSchema.optional(),
  template: promptTemplateSelectionSchema.optional(),
  /** The instruction cites references[N-1] as [ref N]. */
  references: z.array(promptReferenceSchema).max(20).optional()
};
export const editModeSchema = z.enum(['in-place', 'variant']);
export const replaceModeSchema = z.enum(['diagram', 'subnode-single', 'multi-contiguous', 'multi-disjoint']);
const subtreeSchema = z.object({ contentNodeId: z.string().min(1).max(500), revisionId: id }).strict();
const generationSchema = z.object({
  'presentation-alternative': z.object({ name: z.string().trim().min(1).max(120), select: z.boolean().default(false) }).strict().optional().describe('Promote this variant as a named presentation alternative. Requires edit-mode variant. select defaults to false.'),
  'source-mappings': z.boolean().optional().describe('Defaults to false. Enable to supply new source mappings.'),
  sessionId: id, nodeId: id, expectedVersion: z.number().int().nonnegative(),
  'edit-mode': editModeSchema.optional(),
  'replace-mode': replaceModeSchema.optional(),
  variant: z.object({ name: z.string().trim().min(1).max(120), count: z.number().int().min(1).max(4).default(1), variantId: id.optional() }).strict().optional(),
  subtree: subtreeSchema.optional(),
  subtrees: z.array(subtreeSchema).min(2).max(100).optional(),
  origin: z.object({ column: z.number().int().nonnegative(), row: z.number().int().nonnegative() }).strict().optional(),
  sources: z.array(contentNodeAnchorSchema).max(500).optional(),
  baseRevisionId: id, agentContextId: id.optional(), prompt: z.string().trim().min(1).max(20000), requestId: id, ...promptFields
}).strict();
export const editDiagramSchema = generationSchema.extend({
  'edit-mode': editModeSchema.describe('Required. in-place applies the edit; variant saves an alternative.'),
  'replace-mode': replaceModeSchema.describe('Required. diagram: no subtree targets; subnode-single: subtree; multi-contiguous: adjacent subtrees; multi-disjoint: separate subtrees. Supply subtrees for either multi mode.')
}).strict();
/** nodeId/baseRevisionId pin the anchor diagram: its revision is the context and new diagrams are placed beside it. */
export const createDiagramSchema = generationSchema.extend({ count: z.number().int().min(1).max(4).optional() }).strict();
export const extendDiagramSchema = generationSchema.extend({ origin: editDiagramSchema.shape.origin.unwrap(), sources: z.array(contentNodeAnchorSchema).min(1).max(500) }).strict();
export const diagramEditRunSchema = z.object({ runId: id }).strict();
export type EditDiagramInput = z.infer<typeof editDiagramSchema>;
export type CreateDiagramInput = z.infer<typeof createDiagramSchema>;
export interface DiagramRevisionApplication {
  variants?: { variant: import('../../core/diagrams/diagramRevisionReview').DiagramRevisionReview; revision: DiagramRevision; alternative?: import('../../core/presentation/diagramAlternative').DiagramAlternative; selectAlternative?: boolean }[];
  requestId: string;
  expectedVersion: number;
  nodeId: string;
  baseRevisionId: string;
  revision: DiagramRevision;
}
/** A created diagram, placed by the canvas in one undoable update. */
export interface DiagramCreation {
  id: string; parentId?: string; position: { column: number; row: number };
  content: Omit<DiagramInput, 'id' | 'revision'>;
  sources?: ContentNodeAnchor[];
}
export interface DiagramEditRun {
  variants?: { id: string; name: string; revisionId: string; alternativeId?: string }[];
  /** Actual runtime session for diagnostics/clipboard; each run may have a new ID. */
  agentSessionId?: string;
  /** Updated conversation, published only after the canvas acknowledges success. */
  agentContext?: AgentContextSnapshot;
  runId: string;
  operation: PromptOperation;
  status: 'generating' | 'applying' | 'completed' | 'conflict' | 'failed' | 'cancelled' | 'awaiting-acknowledgement';
  nodeId: string;
  baseRevisionId: string;
  message?: string;
  error?: string;
  generated?: { diagramId: string; revisionId: string; ascii: string };
  result?: { diagramId: string; previousRevisionId: string; revisionId: string; documentVersion: number; unresolvedEdgeIds: string[] };
  /** create-diagram only: the new canvas nodes, in generation order. */
  created?: { documentVersion: number; nodeIds: string[] };
}

sources.domain/mapping/changes/canvasViewDiff.ts:
import { alternativeSelections, emptyDiagramAlternatives } from '../../core/presentation/diagramAlternative';
import { presentationHighlights } from '../../core/presentation/diagramPresentation';
import { rebaseDiagramHighlights, type DiagramHighlight } from '../../core/diagrams/diagramHighlight';
import type { CanvasViewComparison, CanvasViewSnapshot } from '../../core/diagrams/canvasView';
import { buildDiagramContent } from '../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { resolveRevisionLines } from '../../core/diagrams/diagramRevisionSelection';
import type { DiagramAnchor } from '../../core/diagrams/diagramConnection';
import type { GridBox } from '../../core/diagrams/lineGrid';
import type { ChangeDocumentState, ChangePreviewDocument } from './diagramChangeSession';
import type { MappingCanvasState } from '../workspace/mappingWorkspace';
import { diffChangeDocument } from './changeDocumentDiff';

const diagramBoxes = (root: GridBox, origin = { column: 0, row: 0 }): Extract<GridBox, { kind: 'diagram' }>[] => {
  const position = { column: origin.column + root.position.column, row: origin.row + root.position.row };
  return root.kind === 'diagram' ? [{ ...root, position }] : root.children.flatMap(child => diagramBoxes(child, position));
};

/** Rendering projection only: never issues revisions or changes the stored selection. */
function project(snapshot: CanvasViewSnapshot) {
  const document = structuredClone(snapshot.document);
  const identities = new Map<string, Map<string, string>>();
  const replacements = new Map<string, string>();
  const placements = diagramBoxes(document.scene.root);
  const rename = new Map<string, string>();
  for (const box of placements) {
    const originalContentId = box.contentId;
    const contentId = placements.filter(other => other.contentId === originalContentId).length > 1 ? `placement:${box.id}:${originalContentId}` : originalContentId;
    const diagram = { ...snapshot.document.scene.contents[originalContentId], id: contentId };
    rename.set(box.id, contentId);
    document.scene.contents = { ...document.scene.contents, [contentId]: diagram };
    if (document.diagramPresentations?.[originalContentId]) document.diagramPresentations[contentId] = document.diagramPresentations[originalContentId];
    const choices = alternativeSelections(document, `grid:${box.id}`, originalContentId, snapshot.revisions[diagram.revisionId]);
    const revision = snapshot.revisions[diagram.revisionId];
    const hasSelection = Object.values(choices.revisionSelections ?? {}).some(selection => selection.contentId === originalContentId);
    let refs: Record<string, string> = { ...revision.nodeRefs };
    if (hasSelection) {
      const rows = resolveRevisionLines(revision, choices, id => snapshot.revisions[id]);
      const ascii = rows.map(row => row.revision.diagram.content.ascii.split('\n')[row.sourceLine - 1]).join('\n');
      const structure = rows[0]?.revision.diagram.content.structure ?? diagram.content.structure;
      const content = buildDiagramContent(ascii, diagram.content.revisionId, structure.kind,
        structure.kind === 'tree' ? structure.parserVersion : undefined);
      refs = {};
      const remap = new Map<string, string>();
      for (const node of diagramContentNodes(content)) {
        const row = rows[node.line - 1];
        const source = diagramContentNodes(row.revision.diagram.content).find(n => n.line === row.sourceLine && n.startColumn === node.startColumn);
        if (source && row.revision.nodeRefs[source.id]) { refs[node.id] = row.revision.nodeRefs[source.id]; remap.set(source.id, node.id); }
      }
      // Variant rows carry their own evidence and coordinates; never reuse the base's stale spans.
      const evidence: Record<string, typeof diagram.sourceContext.evidence[string]> = {};
      const mappings = rows.flatMap((row, index) => row.revision.diagram.sourceContext.mappings.filter(m => m.line === row.sourceLine).map(mapping => {
        const entityId = `${row.revision.id}:${mapping.entityId}`;
        evidence[entityId] = { ...row.revision.diagram.sourceContext.evidence[mapping.entityId], id: entityId };
        return { ...mapping, id: `${row.revision.id}:${mapping.id}:${index}`, entityId, line: index + 1 };
      }));
      const byRef = new Map(Object.entries(refs).map(([id, ref]) => [ref, id]));
      const sourceHighlights = [...new Map(rows.flatMap(row => presentationHighlights(row.revision.diagram, document.diagramPresentations?.[contentId], row.revision.nodeRefs)
        .filter(item => !item.textRange).map(item => [item.id, item] as const))).values()];
      const highlights: DiagramHighlight[] = rebaseDiagramHighlights(sourceHighlights, remap).map(({ nodeRefs, ...item }) => {
        const ids = nodeRefs?.map(ref => byRef.get(ref) ?? `stale:${ref}`);
        return ids?.length ? { ...item, ...(item.contentNodeIds ? { contentNodeIds: ids } : { contentNodeId: ids[0] }) } : item;
      });
      // A composed row only inherits a text annotation from its exact source revision.
      rows.forEach((row, index) => {
        for (const item of presentationHighlights(row.revision.diagram, document.diagramPresentations?.[contentId], row.revision.nodeRefs)) {
          const range = item.textRange;
          if (!range || item.revisionId !== row.revision.id || row.sourceLine < range.startLine || row.sourceLine > range.endLine) continue;
          const length = row.revision.diagram.content.ascii.split('\n')[row.sourceLine - 1].length;
          if (!length) continue;
          highlights.push({ ...item, id: `${item.id}:row:${index}`, revisionId: diagram.revisionId,
            textRange: { startLine: index + 1, endLine: index + 1,
              startColumn: row.sourceLine === range.startLine ? range.startColumn : 1,
              endColumn: row.sourceLine === range.endLine ? range.endColumn : length } });
        }
      });
      document.diagramPresentations = { ...document.diagramPresentations, [contentId]: { ...document.diagramPresentations?.[contentId], highlights } };
      document.scene.contents = { ...document.scene.contents, [contentId]: { ...diagram, content, highlights, jumps: [],
        sourceContext: { ...diagram.sourceContext, contentHash: content.asciiSha256, mappings, evidence } } };
    }
    const byRef = new Map(Object.entries(refs).map(([id, ref]) => [ref, id]));
    identities.set(contentId, byRef);
    for (const [id, ref] of Object.entries(revision.nodeRefs)) {
      const target = byRef.get(ref); if (target) replacements.set(`grid:${box.id}:${id}`, target);
    }
  }
  const rebind = (box: GridBox): GridBox => box.kind === 'container' ? { ...box, children: box.children.map(rebind) } : { ...box, contentId: rename.get(box.id)! };
  document.scene.root = rebind(document.scene.root);
  const boxes = new Map(diagramBoxes(document.scene.root).map(box => [`grid:${box.id}`, box]));
  const anchor = (value: DiagramAnchor): DiagramAnchor | undefined => {
    if (value.kind === 'box') return value;
    const box = boxes.get(value.displayNodeId), contentNodeId = replacements.get(`${value.displayNodeId}:${value.contentNodeId}`);
    if (!box || !contentNodeId) return undefined;
    return { ...value, contentNodeId, revisionId: document.scene.contents[box.contentId].content.revisionId };
  };
  document.edges = document.edges.flatMap(edge => {
    const source = anchor(edge.source), target = anchor(edge.target);
    return source?.kind === 'content-node' && target ? [{ ...edge, source, target }] : [];
  });
  // These are already represented by the projected rows. Preview does not offer live navigation.
  document.alternatives = emptyDiagramAlternatives(); document.revisionSelections = {}; document.jumps = [];
  return { state: { document, canvas: structuredClone(snapshot.view) as MappingCanvasState } satisfies ChangeDocumentState, identities };
}

export function canvasViewDiff(comparison: CanvasViewComparison) {
  const before = project(comparison.baseline), after = project(comparison.proposed);
  const correspondence: Record<string, string> = {};
  for (const [contentId, refs] of after.identities) for (const [ref, id] of refs) {
    const old = before.identities.get(contentId)?.get(ref);
    if (old) correspondence[id] = old;
  }
  const doc: ChangePreviewDocument = { id: `view:${comparison.view.id}:${comparison.proposed.checkpointId}`,
    name: comparison.view.name, version: 0, baseline: before.state, proposed: after.state };
  const diff = diffChangeDocument(doc, correspondence);
  const beforeBoxes = diagramBoxes(before.state.document.scene.root), afterBoxes = diagramBoxes(after.state.document.scene.root);
  const beforeIds = new Set(beforeBoxes.map(box => `grid:${box.id}`)), afterIds = new Set(afterBoxes.map(box => `grid:${box.id}`));
  const removedDiagramIds = new Set([...beforeIds].filter(id => !afterIds.has(id)));
  const modifiedDiagramIds = new Set([...afterIds].filter(id => beforeIds.has(id)));
  // Retain deleted diagrams as ghost boxes in the preview, without restoring them to the canvas.
  const ghosts = beforeBoxes.filter(box => removedDiagramIds.has(`grid:${box.id}`)).map(box => {
    const contentId = `removed:${box.id}:${box.contentId}`;
    const diagram = before.state.document.scene.contents[box.contentId];
    doc.proposed.document.scene.contents = { ...doc.proposed.document.scene.contents, [contentId]: { ...diagram, id: contentId } };
    doc.proposed.document.diagramPresentations = { ...doc.proposed.document.diagramPresentations, [contentId]: before.state.document.diagramPresentations?.[box.contentId] ?? { highlights: diagram.highlights } };
    return { ...box, contentId, collapsedContentId: undefined, collapsed: false };
  });
  if (ghosts.length) {
    const root = doc.proposed.document.scene.root;
    doc.proposed.document.scene.root = { id: `view-root:${comparison.view.id}`, kind: 'container', position: { column: 0, row: 0 },
      collapsed: false, layout: { collisionPolicy: 'push-right', gap: 3 }, children: [root, ...ghosts] };
  }
  return { doc, diff, modifiedDiagramIds, removedDiagramIds };
}

sources.domain/mapping/workspace/canvasDisplayNo:
import { alternativeSelections } from '../../core/presentation/diagramAlternative';
import { projectSelectedDiagramRows, selectedDiffAlternative } from '../../core/presentation/diagramRevisionProjection';
import { resolveRevisionLines } from '../../core/diagrams/diagramRevisionSelection';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { getDiagramRevision } from '../../core/diagrams/diagramRevisionStore';
import { diagramNode, type DiagramNode, type DiagramPresentation } from '../../core/diagrams/diagramNode';
import { presentationHighlights } from '../../core/presentation/diagramPresentation';
import { endpointKey, type EndpointBounds } from './endpointGeometry';
import { presentationScene, resolveDiagramContent, projectDiagramContent, resolveDiagramView } from './diagramViewState';
export { resolveDiagramContent } from './diagramViewState';
import { flattenGrid, resolveScene, type GridBounds } from '../../core/diagrams/lineGrid';
import type { DiagramContent } from '../../core/diagrams/diagramContent';
import type { FloatingBox, DisplayGeometry } from './displayModel';
import type { MappingGridDocument } from './mappingGrid';
import type { MappingCanvasState } from './mappingWorkspace';
import { drawEdge, resolveEndpoint, spaceEdgeArrows } from './connectionLayout';
import { connectionContentNodes } from '../../core/diagrams/diagramConnection';
import { connectionObstacles, sceneRoutingObstacles } from './routingObstacles';
export type { FloatingBox };

export type FloatingPlacement =
  | { kind: 'connection'; edgeId: string }
  | { kind: 'grid-region'; gridBoxId: string; contentId: string; rect: import('../selection/mappingPoc').MappingPocGridRect; sourceAscii: string }
  | { kind: 'parent'; ownerId: string }
  | { kind: 'conversation'; canvasAnchor: { x: number; y: number }; presentation: 'compact' | 'floating' | 'docked' }
  | { kind: 'stored'; coordinateSpace: 'canvas' | 'viewport' };
export interface DisplayNodeCollapsible {
  self: boolean;
  subtrees: {
    contentNodeId: string; label: string; line: number; branchColumn: number;
    /** Zero-based row in the folded rendering; absent when hidden by an ancestor. */
    visibleRow?: number;
    expansion: 'expanded' | 'collapsed';
  }[];
}
export type CanvasDisplayNode = {
  presentationSettings?: import('../../core/presentation/diagramPresentation').DiagramPresentationSettings;
  textRows?: readonly import('../../core/presentation/diagramText').DiagramTextRow[];
  domainNode?: DiagramNode; presentation?: DiagramPresentation;
  id: string; version: number; childIds: string[]; expansion: 'expanded' | 'collapsed';
  collapsible: DisplayNodeCollapsible;
} & ({ layout: 'grid'; kind: 'diagram' | 'group'; boxId: string; geometry: { units: 'cells'; bounds: GridBounds }; content?: DiagramContent; nodeRefs?: Readonly<Record<string, string>>; contentNodes?: readonly import('../../core/diagrams/diagramContent').DiagramContentNode[]; diagram?: import("../../core/diagrams/diagram").Diagram }
  | { layout: 'floating'; kind: FloatingBox['kind']; geometry: DisplayGeometry & { units: 'pixels' }; placement: FloatingPlacement; value: FloatingBox });
export const gridNodeId = (id: string) => `grid:${id}`;
export const floatingNodeId = (id: string) => `floating:${id}`;

/** Read-only registry over the two existing stores. Geometry has no second writable copy. */
export function canvasDisplayNodes(document: MappingGridDocument, canvas: MappingCanvasState, version: number, cell = { width: 8, height: 18 }, endpointBounds?: EndpointBounds): CanvasDisplayNode[] {
  const visible = new Map(flattenGrid(resolveDiagramView(presentationScene(document), canvas.diagramViews)).map(node => [node.box.id, node]));
  const expand = (box: typeof document.scene.root): typeof box => box.kind === 'container'
    ? { ...box, collapsed: false, children: box.children.map(expand) } : { ...box, collapsed: false };
  const expanded = flattenGrid(resolveScene({ ...document.scene, root: expand(document.scene.root) }));
  const grid: CanvasDisplayNode[] = expanded.map(node => {
    const box = findBox(document.scene.root, node.box.id)!;
    const content = box.kind === 'diagram' ? document.scene.contents[box.contentId] : undefined;
    const parsed = content && resolveDiagramContent(content);
    const view = canvas.diagramViews?.[gridNodeId(box.id)];
    const projection = parsed && projectDiagramContent(parsed, view);
    const revision = content && getDiagramRevision(content.revisionId);
    const collapsedRefs = new Set([...(view?.collapsedNodeRefs ?? []), ...(view && view.contentRevisionId === parsed?.revisionId ? view.collapsedContentNodeIds : []).flatMap(id => revision?.nodeRefs[id] ? [revision.nodeRefs[id]] : [])]);
    const choices = alternativeSelections(document, `grid:${box.id}`, content?.id ?? "", revision);
    const selected = revision && Object.values(choices.revisionSelections ?? {}).some(selection => selection.contentId === content!.id);
    const diffAlternative = selectedDiffAlternative(document, gridNodeId(box.id));
    const selectedLines = selected ? resolveRevisionLines(revision, choices, getDiagramRevision, collapsedRefs) : undefined;
    const selectedNodes = new Map<string, Map<number, import('../../core/diagrams/diagramContent').DiagramContentNode>>();
    const selectedSubtrees = selectedLines?.flatMap((line, visibleRow) => {
      if (!selectedNodes.has(line.revision.id)) selectedNodes.set(line.revision.id, new Map(diagramContentNodes(line.revision.diagram.content).map(node => [node.line, node])));
      const item = selectedNodes.get(line.revision.id)!.get(line.sourceLine);
      return item?.childIds.length ? [{ contentNodeId: item.id, label: item.label, line: item.line, branchColumn: item.branchColumn, visibleRow,
        expansion: collapsedRefs.has(line.nodeRef!) ? 'collapsed' as const : 'expanded' as const }] : [];
    });
    return { collapsible: { self: box.id !== document.scene.root.id, subtrees: diffAlternative ? [] : selectedSubtrees ?? (parsed?.structure.kind === 'tree' ? Object.values(parsed.structure.nodes).filter(item => item.childIds.length).map(item => ({
      contentNodeId: item.id, label: item.label, line: item.line, branchColumn: item.branchColumn, visibleRow: projection!.rowForLine(item.line),
      expansion: view?.contentRevisionId === parsed.revisionId && view.collapsedContentNodeIds.includes(item.id) ? 'collapsed' as const : 'expanded' as const
    })) : []) }, id: gridNodeId(box.id), boxId: box.id, version, layout: 'grid', kind: box.kind === 'diagram' ? 'diagram' : 'group',
      childIds: box.kind === 'container' ? box.children.map(child => gridNodeId(child.id)) : [], expansion: box.collapsed ? 'collapsed' : 'expanded',
      geometry: { units: 'cells', bounds: visible.get(box.id)?.bounds ?? node.bounds },
      ...(content ? (() => {
        const refs = getDiagramRevision(content.revisionId).nodeRefs;
        const highlights = presentationHighlights(content, document.diagramPresentations?.[content.id], refs);
        const domainNode = diagramNode(gridNodeId(box.id), content);
        const bounds = visible.get(box.id)?.bounds ?? node.bounds;
        const presentation: DiagramPresentation = { id: domainNode.id, nodeId: domainNode.id,
          geometry: { coordinateSpace: 'canvas', position: { x: bounds.column * cell.width, y: bounds.row * cell.height }, bounds: { width: bounds.columns * cell.width, height: bounds.rows * cell.height } },
          view: { alternativeIds: Object.values(document.alternatives?.items ?? {}).filter(a => a.presentationId === domainNode.id).map(a => a.id),
            selectedAlternativeIds: document.alternatives?.selected[domainNode.id] ?? [], sidePanelIds: Object.values(document.alternatives?.panels ?? {}).filter(p => p.attachment.diagramPresentationId === domainNode.id).map(p => p.id),
            display: diffAlternative ? 'diff' : view?.display ?? 'regular', baseRevisionId: diffAlternative?.parts[0].baseRevisionId ?? view?.baseRevisionId, collapsed: box.collapsed, collapsedNodeRefs: [...collapsedRefs], highlights } };
        const textRows = selected
          ? projectSelectedDiagramRows(revision!, document, domainNode.id, getDiagramRevision, document.diagramPresentations?.[content.id], collapsedRefs) : undefined;
        return { domainNode, presentation, textRows, presentationSettings: document.diagramPresentations?.[content.id], content: content.content, contentNodes: connectionContentNodes(content.content), nodeRefs: refs,
          diagram: highlights === content.highlights ? content : { ...content, highlights } };
      })() : {}) };
  });
  const floating: CanvasDisplayNode[] = Object.values(canvas.display.nodes).map(node => {
    const owner = Object.values(canvas.display.nodes).find(parent => parent.childIds.includes(node.id));
    const placement: FloatingPlacement = node.kind === 'selection' && node.geometryPolicy.placement === 'automatic'
      ? { kind: 'grid-region', gridBoxId: gridNodeId(node.sourceBoxId), contentId: node.sourceContentId, rect: node.rect, sourceAscii: node.sourceAscii }
      : node.kind === 'conversation' ? { kind: 'conversation', canvasAnchor: node.canvasAnchor, presentation: node.presentation }
      : node.kind === 'projection' && owner && node.geometryPolicy.placement === 'automatic'
        ? { kind: 'parent', ownerId: floatingNodeId(owner.id) } : { kind: 'stored', coordinateSpace: node.coordinateSpace };
    return { collapsible: { self: true, subtrees: [] }, id: floatingNodeId(node.id), version, layout: 'floating', kind: node.kind,
      childIds: node.childIds.map(floatingNodeId), expansion: node.expansion,
      geometry: { units: 'pixels', position: node.position, bounds: node.bounds, coordinateSpace: node.coordinateSpace }, placement, value: node };
  });
  const obstacles = document.edges?.length ? sceneRoutingObstacles(document.scene, canvas.diagramViews, cell) : [];
  const spaced = spaceEdgeArrows((document.edges ?? []).map(edge => {
    const a = resolveEndpoint(document.scene, canvas.diagramViews, edge.source, cell);
    const b = resolveEndpoint(document.scene, canvas.diagramViews, edge.target, cell, true);
    return { arrow: drawEdge(edge, document.scene, canvas.diagramViews, cell, endpointBounds, obstacles),
      obstacles: [...connectionObstacles(obstacles, a?.identity, b?.identity), ...[a, b].flatMap(endpoint => endpoint
        ? [(!endpoint.labelRect && endpointBounds?.[endpointKey(endpoint.identity)]) || endpoint.rect] : [])] };
  }));
  const arrows: CanvasDisplayNode[] = spaced.map(value => {
    return { id: `floating:${value.id}`, version, childIds: [], expansion: 'expanded', collapsible: { self: false, subtrees: [] },
      layout: 'floating', kind: 'arrow', geometry: { units: 'pixels', position: value.position, bounds: value.bounds, coordinateSpace: 'canvas' },
      placement: { kind: 'connection', edgeId: value.edgeId }, value };
  });
  return structuredClone([...grid, ...floating, ...arrows]);
}
export function findBox(box: import('../../core/diagrams/lineGrid').GridBox, id: string): typeof box | undefined {
  if (box.id === id) return box;
  return box.kind === 'container' ? box.children.map(child => findBox(child, id)).find(Boolean) : undefined;
}

